# ================================================================#  WINDOWS 11 - USB & NETWORK ADAPTER OPTIMIZATION##  PowerShell script prepared for easy and quick optimization#  of advanced device configuration settings:# #  - Intel(R) Wi-Fi 6E AX210 160MHz #    (PCI\VEN_8086&DEV_2725&SUBSYS_00248086&REV_1A\4&1E1F98A2&0&00E8)##  - Realtek Gaming 2.5GbE Family Controller#    PCI\VEN_10EC&DEV_8125&SUBSYS_E0001458&REV_05\01000000684CE00000##  Additionally disables the USB power saving feature #  (USB Selective Suspend)###  About all features:##  USB:#    - USB Selective Suspend -> Disabled##  ALL NETWORK ADAPTERS:#    - Windows network adapter power management -> Disabled##  INTEL:#    - Intel Wi-Fi 6E AX210 160MHz#    - Device power management -> Disabled#    - MIMO Power Save Mode -> No SMPS#    - Transmit Power -> Highest#    - Roaming Aggressiveness -> Lowest#    - Throughput Booster -> Enabled#    - U-APSD support -> Disabled##  REALTEK:#    - Realtek Gaming 2.5GbE / RTL8125#    - EEE / Green Ethernet / Gigabit Lite -> Disabled#    - Interrupt Moderation -> Disabled#    - Power Saving Mode -> Disabled#    - Receive / Transmit Buffers -> 4096#    - Wake-on-LAN related options -> Disabled / optimized#    - Speed & Duplex -> 2.5 Gbps Full Duplex#    - Priority & VLAN -> Priority Enabled###       Script name:   WIN11_SET_ADV_DEV_OPT_NET_USB_PWR_V3.ps1#           Version:   3.0#            Author:   Jacek Zaczek#              Date:   06.09.2026#            GitHub:   https://github.com/aurenhexliner## ================================================================$ErrorActionPreference = "Continue"# ================================================================#  GENERAL# ================================================================$logLines = @()$logLines += "Windows 11 - USB & Network Adapter Optimization"$logLines += "================================================"$logLines += "Time: $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')"$logLines += ""function Add-Log {    param(        [string]$Message    )    $script:logLines += $Message}function Write-Section {    param(        [string]$Title    )    Write-Host ""    Write-Host "================================================================" -ForegroundColor DarkGray    Write-Host "  $Title" -ForegroundColor Cyan    Write-Host "================================================================" -ForegroundColor DarkGray    Write-Host ""}function Get-CurrentAdvancedValue {    param(        [string]$AdapterName,        [string[]]$DisplayNames    )    foreach ($name in $DisplayNames) {        try {            $prop = Get-NetAdapterAdvancedProperty `                -Name $AdapterName `                -DisplayName $name `                -ErrorAction Stop            if ($null -ne $prop) {                return $prop            }        }        catch {            # Try next alias.        }    }    return $null}function Set-AdvancedProperty {    param(        [string]$AdapterName,        [string[]]$DisplayNames,        [string]$DesiredValue,        [string]$Description    )    $property = Get-CurrentAdvancedValue `        -AdapterName $AdapterName `        -DisplayNames $DisplayNames    if ($null -eq $property) {        Write-Host "[INFO] $Description - property not available on this driver." `            -ForegroundColor DarkYellow        Add-Log "$Description | Not available"        return    }    $current = $property.DisplayValue    if ($current -eq $DesiredValue) {        Write-Host "[OK]   $Description -> $current" `            -ForegroundColor Green        Add-Log "$Description | Already correct | $current"        return    }    Write-Host "[CHANGE] $Description" -ForegroundColor Yellow    Write-Host "        Current : $current" -ForegroundColor DarkYellow    Write-Host "        Desired : $DesiredValue" -ForegroundColor Yellow    $success = $false    foreach ($name in $DisplayNames) {        try {            Set-NetAdapterAdvancedProperty `                -Name $AdapterName `                -DisplayName $name `                -DisplayValue $DesiredValue `                -NoRestart `                -ErrorAction Stop            Write-Host "[OK]   Changed -> $name = $DesiredValue" `                -ForegroundColor Cyan            Add-Log "$Description | Changed | $current -> $DesiredValue"            $success = $true            break        }        catch {            # Try next alias.        }    }    if (-not $success) {        Write-Host "[FAIL] Could not change: $Description" `            -ForegroundColor Red        Add-Log "$Description | FAILED | Desired: $DesiredValue"    }}# ================================================================# 1. USB POWER MANAGEMENT# ================================================================Write-Section "1. USB POWER MANAGEMENT"# USB Settings subgroup$usbSubGroup = "2a737441-1930-4402-8d77-b2bebba308a3"# USB selective suspend setting$usbSelectiveSuspend = "48e6b7a6-50f5-4782-a5d4-53bb8f07e226"try {    powercfg /setacvalueindex scheme_current `        $usbSubGroup `        $usbSelectiveSuspend `        0    powercfg /setdcvalueindex scheme_current `        $usbSubGroup `        $usbSelectiveSuspend `        0    powercfg /setactive scheme_current    Write-Host "[OK] USB selective suspend -> Disabled" `        -ForegroundColor Green    Add-Log "USB selective suspend | Disabled"}catch {    Write-Host "[FAIL] Could not change USB selective suspend." `        -ForegroundColor Red    Add-Log "USB selective suspend | FAILED"}# ================================================================# 2. ALL NETWORK ADAPTERS - POWER MANAGEMENT# ================================================================Write-Section "2. ALL NETWORK ADAPTERS - POWER MANAGEMENT"Get-NetAdapter | ForEach-Object {    try {        Disable-NetAdapterPowerManagement `            -Name $_.Name `            -ErrorAction Stop        Write-Host "[OK]   Power management disabled:" `            -ForegroundColor Green        Write-Host "       $($_.Name)"        Add-Log "Network adapter power management | $($_.Name) | Disabled"    }    catch {        Write-Host "[WARN] Could not change power management:" `            -ForegroundColor Yellow        Write-Host "       $($_.Name)"        Add-Log "Network adapter power management | $($_.Name) | FAILED"    }}# ================================================================# 3. INTEL WI-FI 6E AX210 160MHz# ================================================================Write-Section "3. INTEL WI-FI 6E AX210 160MHz"$wifiAdapter = Get-NetAdapter |    Where-Object {        $_.InterfaceDescription -like "*Intel(R) Wi-Fi 6E AX210*"    } |    Select-Object -First 1if ($wifiAdapter) {    Write-Host "Target adapter:" -ForegroundColor Cyan    Write-Host "  Name        : $($wifiAdapter.Name)"    Write-Host "  Description : $($wifiAdapter.InterfaceDescription)"    Write-Host "  Status      : $($wifiAdapter.Status)"    Write-Host "  Link Speed  : $($wifiAdapter.LinkSpeed)"    Write-Host ""    Add-Log "Intel AX210 detected | $($wifiAdapter.Name)"    # ------------------------------------------------------------    # 3.1 DEVICE MANAGER POWER MANAGEMENT    # ------------------------------------------------------------    Write-Host "------------------------------------------------------------" `        -ForegroundColor DarkGray    Write-Host "  3.1 Device Manager - Power Management" `        -ForegroundColor Cyan    Write-Host "------------------------------------------------------------"    Write-Host ""    $wifiDevice = Get-PnpDevice |        Where-Object {            $_.FriendlyName -like "*Intel(R) Wi-Fi 6E AX210*"        }    foreach ($device in $wifiDevice) {        $devicePath =            "HKLM:\SYSTEM\CurrentControlSet\Enum\$($device.InstanceId)\Device Parameters"        if (Test-Path $devicePath) {            try {                Set-ItemProperty `                    -Path $devicePath `                    -Name "PnPCapabilities" `                    -Value 0x18 `                    -Type DWord `                    -Force                Write-Host "[OK]   Allow computer to turn off device -> Disabled" `                    -ForegroundColor Green                Write-Host "       PnPCapabilities = 0x18"                Add-Log "Intel AX210 Device Power Management | Disabled | PnPCapabilities=0x18"            }            catch {                Write-Host "[FAIL] Could not set PnPCapabilities." `                    -ForegroundColor Red                Add-Log "Intel AX210 Device Power Management | FAILED"            }        }        else {            Write-Host "[WARN] Device Parameters registry path not found." `                -ForegroundColor Yellow            Add-Log "Intel AX210 Device Parameters path | NOT FOUND"        }    }    # ------------------------------------------------------------    # 3.2 ADVANCED DRIVER SETTINGS    # ------------------------------------------------------------    Write-Host ""    Write-Host "------------------------------------------------------------" `        -ForegroundColor DarkGray    Write-Host "  3.2 Intel Driver - Advanced Properties" `        -ForegroundColor Cyan    Write-Host "------------------------------------------------------------"    Write-Host ""    # MIMO Power Save Mode -> No SMPS    # Registry value confirmed for this driver:    # Auto SMPS    = 0    # Static SMPS  = 1    # Dynamic SMPS = 2    # No SMPS      = 3    try {        $mimo = Get-NetAdapterAdvancedProperty `            -Name $wifiAdapter.Name `            -AllProperties `            -ErrorAction Stop |            Where-Object {                $_.RegistryKeyword -eq "MIMOPowerSaveMode"            } |            Select-Object -First 1        if ($mimo) {            if ($mimo.DisplayValue -eq "No SMPS") {                Write-Host "[OK]   MIMO Power Save Mode -> No SMPS" `                    -ForegroundColor Green                Add-Log "Intel AX210 MIMO Power Save Mode | Already correct | No SMPS"            }            else {                try {                    Set-NetAdapterAdvancedProperty `                        -Name $wifiAdapter.Name `                        -RegistryKeyword "MIMOPowerSaveMode" `                        -RegistryValue 3 `                        -NoRestart `                        -ErrorAction Stop                    Write-Host "[OK]   MIMO Power Save Mode -> No SMPS" `                        -ForegroundColor Green                    Add-Log "Intel AX210 MIMO Power Save Mode | Changed -> No SMPS"                }                catch {                    Write-Host "[FAIL] Could not set MIMO Power Save Mode." `                        -ForegroundColor Red                    Add-Log "Intel AX210 MIMO Power Save Mode | FAILED"                }            }        }        else {            Write-Host "[INFO] MIMO Power Save Mode not available." `                -ForegroundColor DarkYellow            Add-Log "Intel AX210 MIMO Power Save Mode | NOT AVAILABLE"        }    }    catch {        Write-Host "[FAIL] Could not read MIMO Power Save Mode." `            -ForegroundColor Red    }    # Transmit Power -> Highest    Set-AdvancedProperty `        -AdapterName $wifiAdapter.Name `        -DisplayNames @("Transmit Power") `        -DesiredValue "5. Highest" `        -Description "Transmit Power"    # Roaming Aggressiveness -> Lowest    Set-AdvancedProperty `        -AdapterName $wifiAdapter.Name `        -DisplayNames @("Roaming Aggressiveness") `        -DesiredValue "1. Lowest" `        -Description "Roaming Aggressiveness"    # Throughput Booster -> Enabled    Set-AdvancedProperty `        -AdapterName $wifiAdapter.Name `        -DisplayNames @("Throughput Booster") `        -DesiredValue "Enabled" `        -Description "Throughput Booster"    # U-APSD -> Disabled    Set-AdvancedProperty `        -AdapterName $wifiAdapter.Name `        -DisplayNames @("U-APSD support", "U-APSD Support") `        -DesiredValue "Disabled" `        -Description "U-APSD support"}else {    Write-Host "[INFO] Intel AX210 Wi-Fi adapter not found." `        -ForegroundColor DarkYellow    Add-Log "Intel AX210 | NOT FOUND"}# ================================================================# 4. REALTEK 2.5GbE / RTL8125# ================================================================Write-Section "4. REALTEK 2.5GbE / RTL8125"$realtekAdapter = Get-NetAdapter |    Where-Object {        $_.PnPDeviceID -match 'PCI\\VEN_10EC&DEV_8125' -or        $_.InterfaceDescription -match 'Realtek.*2\.5GbE|Realtek Gaming 2\.5GbE'    } |    Select-Object -First 1if ($realtekAdapter) {    Write-Host "Target adapter:" -ForegroundColor Cyan    Write-Host "  Name        : $($realtekAdapter.Name)"    Write-Host "  Description : $($realtekAdapter.InterfaceDescription)"    Write-Host "  Status      : $($realtekAdapter.Status)"    Write-Host "  Link Speed  : $($realtekAdapter.LinkSpeed)"    Write-Host ""    Add-Log "Realtek RTL8125 detected | $($realtekAdapter.Name)"    # ------------------------------------------------------------    # 4.1 REALTEK ADVANCED DRIVER SETTINGS    # ------------------------------------------------------------    Write-Host "------------------------------------------------------------" `        -ForegroundColor DarkGray    Write-Host "  4.1 Realtek Driver - Advanced Properties" `        -ForegroundColor Cyan    Write-Host "------------------------------------------------------------"    Write-Host ""    $realtekSettings = @(        @{            DisplayNames = @("EEE Max Support Speed")            DesiredValue = "2.5 Gbps Full Duplex"            Description  = "EEE Max Support Speed"        },        @{            DisplayNames = @("Energy-Efficient Ethernet", "EEE")            DesiredValue = "Disabled"            Description  = "Energy-Efficient Ethernet"        },        @{            DisplayNames = @("Gigabit Lite")            DesiredValue = "Disabled"            Description  = "Gigabit Lite"        },        @{            DisplayNames = @("Green Ethernet")            DesiredValue = "Disabled"            Description  = "Green Ethernet"        },        @{            DisplayNames = @("Interrupt Moderation", "Interrupt Moderation Mode")            DesiredValue = "Disabled"            Description  = "Interrupt Moderation"        },        @{            DisplayNames = @("Power Saving Mode")            DesiredValue = "Disabled"            Description  = "Power Saving Mode"        },        @{            DisplayNames = @("Receive Buffers")            DesiredValue = "4096"            Description  = "Receive Buffers"        },        @{            DisplayNames = @("Transmit Buffers")            DesiredValue = "4096"            Description  = "Transmit Buffers"        },        @{            DisplayNames = @("Shutdown Wake-On-Lan", "Shutdown Wake on LAN")            DesiredValue = "Disabled"            Description  = "Shutdown Wake-On-LAN"        },        @{            DisplayNames = @("Speed Duplex", "Speed & Duplex")            DesiredValue = "2.5 Gbps Full Duplex"            Description  = "Speed & Duplex"        },        @{            DisplayNames = @("Priority & VLAN", "Priority and VLAN")            DesiredValue = "Priority Enabled"            Description  = "Priority & VLAN"        },        @{            DisplayNames = @("Wake On Magic Packet")            DesiredValue = "Disabled"            Description  = "Wake On Magic Packet"        },        @{            DisplayNames = @("Wake on pattern match")            DesiredValue = "Disabled"            Description  = "Wake on pattern match"        },        @{            DisplayNames = @(                "WOL & Shutdown Link Speed",                "Wake-On-LAN Shutdown Link Speed"            )            DesiredValue = "Not Speed Down"            Description  = "WOL & Shutdown Link Speed"        }    )    foreach ($setting in $realtekSettings) {        Set-AdvancedProperty `            -AdapterName $realtekAdapter.Name `            -DisplayNames $setting.DisplayNames `            -DesiredValue $setting.DesiredValue `            -Description $setting.Description    }}else {    Write-Host "[INFO] Realtek RTL8125 / 2.5GbE adapter not found." `        -ForegroundColor DarkYellow    Add-Log "Realtek RTL8125 | NOT FOUND"}# ================================================================# 5. SUMMARY# ================================================================Write-Section "5. OPTIMIZATION SUMMARY"Write-Host "Configured components:" -ForegroundColor CyanWrite-Host ""Write-Host "  [USB]" -ForegroundColor WhiteWrite-Host "    USB Selective Suspend              -> Disabled"Write-Host ""Write-Host "  [ALL NETWORK ADAPTERS]" -ForegroundColor WhiteWrite-Host "    Windows Power Management            -> Disabled"Write-Host ""Write-Host "  [INTEL AX210]" -ForegroundColor WhiteWrite-Host "    Device Power Management             -> Disabled"Write-Host "    MIMO Power Save Mode                -> No SMPS"Write-Host "    Transmit Power                      -> Highest"Write-Host "    Roaming Aggressiveness              -> Lowest"Write-Host "    Throughput Booster                  -> Enabled"Write-Host "    U-APSD support                      -> Disabled"Write-Host ""Write-Host "  [REALTEK RTL8125]" -ForegroundColor WhiteWrite-Host "    EEE / Green Ethernet / Gigabit Lite -> Disabled"Write-Host "    Interrupt Moderation                -> Disabled"Write-Host "    Power Saving Mode                   -> Disabled"Write-Host "    Receive / Transmit Buffers          -> 4096"Write-Host "    Speed & Duplex                      -> 2.5 Gbps Full Duplex"Write-Host "    Priority & VLAN                     -> Priority Enabled"Write-Host "    Wake-on-LAN                         -> Optimized / Disabled"Write-Host ""Add-Log ""Add-Log "Optimization process completed."# ================================================================# 6. SAVE LOG# ================================================================Write-Host "----------------------------------------------------------------" `    -ForegroundColor DarkGray$saveLog = Read-Host "Do you want to save optimization log? (Y/N)"if ($saveLog -match '^(Y|YES|Yes|yes)$') {    $logPath = "C:\WIN11_USB_NETWORK_OPTIMIZATION.log"    try {        $logLines |            Out-File `                -FilePath $logPath `                -Encoding UTF8        Write-Host ""        Write-Host "[OK] Log saved to:" -ForegroundColor Green        Write-Host "     $logPath"    }    catch {        $fallbackPath =            "$env:ProgramData\WIN11_USB_NETWORK_OPTIMIZATION.log"        try {            $logLines |                Out-File `                    -FilePath $fallbackPath `                    -Encoding UTF8            Write-Host ""            Write-Host "[OK] Log saved to:" -ForegroundColor Green            Write-Host "     $fallbackPath"        }        catch {            Write-Host ""            Write-Host "[FAIL] Unable to save log." `                -ForegroundColor Red        }    }}else {    Write-Host ""    Write-Host "[INFO] Log not saved." -ForegroundColor DarkYellow}# ================================================================# FINISHED# ================================================================Write-Host ""Write-Host "================================================================" `    -ForegroundColor DarkGrayWrite-Host "  OPTIMIZATION COMPLETED" -ForegroundColor GreenWrite-Host "================================================================" `    -ForegroundColor DarkGrayWrite-Host ""Write-Host "A restart of Windows is recommended to apply all changes."Write-Host ""Read-Host "Press Enter to exit"